/**
 * Runs inside MapLibre's web workers, loaded once with
 * `maplibregl.importScriptInWorkers` (see `maplibreProjection.ts`).
 * GeoJSON sources are tiled in the workers, so under a projection
 * registered with `addProjection` they need the same proj4 converter as
 * the page, built from the CRS's `definition` string.
 */
import proj4 from 'proj4';

interface ProjectionHandlerScope {
  setProjectionHandler(
    handler: (definition: string) => {
      forward(p: number[]): number[];
      inverse(p: number[]): number[] | null;
    }
  ): void;
}

(self as unknown as ProjectionHandlerScope).setProjectionHandler((definition) => {
  const converter = proj4('EPSG:4326', definition);
  return {
    forward: (p) => converter.forward(p as [number, number]),
    inverse: (p) => {
      const ll = converter.inverse(p as [number, number]);
      return Number.isFinite(ll[0]) && Number.isFinite(ll[1]) ? ll : null;
    }
  };
});
